251	+  const cap = C.cadenceMax * CONFIG.people.run.cadence, v = Math.max(0, speed);
252	+  out.amp = 0; out.cadence = 0; out.flags = 0;
253	+  if (pose === ST_POSE_WALK) { out.amp = ppAmp('walk'); out.cadence = Math.min(cap, ppCadence('walk', v, 1)); }
254	+  else if (pose === ST_POSE_RUN) { out.amp = ppAmp('run'); out.cadence = Math.min(cap, Math.max(ppCadence('run', v, 1), (TAU * v) / ppStride('run', 1))); }
255	+  else if (pose === ST_POSE_JUMP) out.flags = PP_FLAG.jump;   // biên độ 0: không nhún, không lắc, không đổ người; tay chân theo tư thế nhảy cố định
256	+  else if (pose === ST_POSE_PHOTO) out.flags = PP_FLAG.photo;
