262	+  track: ExTrack;
263	+  pose: ExPose;               // đệm lấy mẫu (bank chở pose)
264	+  st: { x: number; y: number; z: number; yaw: number; pose: number };   // trạng thái trả cho slotState
265	+  live: boolean;              // đang hiện
266	+  amp: number; cadence: number; flags: number;   // aVar đang ghi (để biết khi nào phải ghi lại)
267	+}
268	+
269	+const slots: StSlot[] = Array.from({ length: N }, () => ({
270	+  who: 0 as const, name: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
271	+  st: { x: 0, y: 0, z: 0, yaw: 0, pose: 0 }, live: false, amp: -1, cadence: -1, flags: -1
