277	+/* Ghi ma trận và aVar của slot i theo s.st (hoặc thu về scale 0 nếu không hiện); speed cho nhịp bước */
278	+function stPlace(i: number, speed: number): void {
279	+  const s = slots[i];
280	+  if (!mesh || !aVar) return;
281	+  if (!s.live) { mesh.setMatrixAt(i, _zero); mesh.instanceMatrix.needsUpdate = true; return; }
282	+  const t = s.st;
283	+  mesh.setMatrixAt(i, _m.compose(_p.set(t.x, t.y, t.z), _q.setFromAxisAngle(_up, t.yaw), _one));   // hình hướng +X: quay yaw quanh Y ra (cos yaw, 0, −sin yaw)
