285	+  stAvatarVar(t.pose, speed, _var);
286	+  if (_var.amp === s.amp && _var.cadence === s.cadence && _var.flags === s.flags) return;
287	+  const a = aVar.array as Float32Array, o = i * 4, now = shared.uTime.value;
288	+  const ph = now * a[o + 3] + a[o];   // giữ pha liền khi đổi nhịp: φ(now) không nhảy
289	+  a[o] = (((ph - now * _var.cadence) % TAU) + TAU) % TAU; a[o + 1] = _var.amp; a[o + 2] = _var.flags; a[o + 3] = _var.cadence;
