305	+}
306	+
307	+/* Tốc độ danh định theo dáng cho người khác (gói vị trí không có tốc độ) */
308	+const stPoseSpeed = (pose: number) => (pose === ST_POSE_RUN ? C.run : pose === ST_POSE_WALK ? C.walk : 0);
309	+
310	+export const stAvatars = {
311	+  get mesh(): THREE.InstancedMesh | null { return mesh; },
312	+
313	+  /* Dựng lần đầu gọi (lười, ngoài thứ tự dựng cảnh), các lần sau trả lại mesh cũ. Bên gọi thêm vào scene */
314	+  build(): THREE.InstancedMesh {
