354	+    for (let i = 0; i < N; i++) {
355	+      const s = slots[i];
356	+      let name: string | null = null;
357	+      for (const w of walkers) if (w.slot === i) { name = w.name; break; }
358	+      if (i === mySlot) { s.name = name; if (s.who === 2) { s.who = 0; stHide(i); } continue; }   // slot vừa thành của mình: bỏ người khác cũ, chờ setSelf
359	+      if (name === null) { s.name = null; if (s.who === 2) { s.who = 0; stHide(i); } continue; }
360	+      if (name !== s.name || s.who !== 2) { s.name = name; s.who = 2; stHide(i); }
361	+    }
362	+    stRefreshVisible();
363	+  },
364	+
365	+  /* Gói vị trí gộp: w = [slot, x, y, z, yaw, pose, giờ gửi?]; chỉ nhận slot người khác đã biết chủ */
366	+  onPos(w: number[][], nowMs: number): void {
367	+    for (const e of w) {
368	+      const i = e[0], s = slots[i];
369	+      if (!s || i === me || s.who !== 2) continue;
370	+      s.track.feed(e, nowMs, M);
371	+    }
372	+  },
373	+
374	+  /* Mỗi khung: đặt người khác theo mẫu nội suy (pose bậc thang) */
375	+  update(nowMs: number): void {
376	+    const t = nowMs - M.interpSends * 1000 / M.sendHz;
377	+    for (let i = 0; i < N; i++) {
378	+      const s = slots[i];
379	+      if (s.who !== 2) continue;
