388	+
389	+  /* Trạng thái đang hiện của slot (cho nhãn tên, camera dù lượn); null nếu trống hoặc chưa có mẫu */
390	+  slotState(slot: number): { x: number; y: number; z: number; yaw: number; pose: number } | null {
391	+    const s = slots[slot];
392	+    return s && s.live ? s.st : null;
393	+  },
394	+
395	+  /* Tên người ở slot (theo sync, cả slot của mình); null nếu trống hoặc đi một mình */
396	+  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },
